  const key = req.get("Idempotency-Key");
  if (!key) return res.status(400).json({ error: "Idempotency-Key required" });

  const [existing] = await db.query(
    "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, key]
  );
  if (existing) return res.status(200).json(existing);

  try {
    const row = await db.write(
      "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) RETURNING *",
      [req.user.accountId, req.body.sku, req.body.quantity, key]
    );
    res.status(201).json(row);
  } catch (err) {
    if (err.code === "23505") {
      const [row] = await db.query(
        "SELECT * FROM orders WHERE account_id = $1 AND idempotency_key = $2",
        [req.user.accountId, key]
      );
      return res.status(200).json(row);
    }
    throw err;
  }
});
```

Scoping the key to `account_id` (not global) matches the same tenant-isolation pattern the earlier account-scoping fix needs.

